import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Maintaining the Help site","description":"","frontmatter":{},"headers":[],"relativePath":"en/operations/help-site.md","filePath":"en/operations/help-site.md","lastUpdated":1794405696000}`),a={name:`en/operations/help-site.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="maintaining-the-help-site" tabindex="-1">Maintaining the Help site <a class="header-anchor" href="#maintaining-the-help-site" aria-label="Permalink to “Maintaining the Help site”">​</a></h1><p>This Help builds the Markdown in the repository&#39;s <code>help/</code> with VitePress and publishes it on GitHub Pages. It is a static site that uses no app server or API keys. The generator, VitePress 2.0.0-alpha.21, is pinned in the dependency lock. When you update it, run the link check and check it in a browser.</p><h2 id="edit" tabindex="-1">Edit <a class="header-anchor" href="#edit" aria-label="Permalink to “Edit”">​</a></h2><p>Suggest a change from the edit link at the bottom of each page, or edit the Markdown locally. Screenshots are in <code>help/public/images/</code>, and the menus are in <code>help/.vitepress/config.mts</code>.</p><p>The Japanese pages live directly under <code>help/</code>, and the English pages live under <code>help/en/</code> with the same file names. When you change a page, update both. Screenshots are shared between the two languages and are in Japanese. Because the admin console is currently Japanese only, English pages show screen labels as an English translation followed by the original Japanese label in 「 」.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help:dev</span></span></code></pre></div><p>Open the URL shown locally in a browser. The development server is limited to 127.0.0.1.</p><h2 id="build-and-check" tabindex="-1">Build and check <a class="header-anchor" href="#build-and-check" aria-label="Permalink to “Build and check”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help:preview</span></span></code></pre></div><p>A broken internal link makes the build fail. Also check search, the menu, code copying and smartphone width, in both languages.</p><h2 id="publish-to-github-pages" tabindex="-1">Publish to GitHub Pages <a class="header-anchor" href="#publish-to-github-pages" aria-label="Permalink to “Publish to GitHub Pages”">​</a></h2><p>Commit your changes and empty the working tree before running this. You need permission to push to GitHub and to configure Pages.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help:publish</span></span></code></pre></div><p>Only the built files are updated on <code>gh-pages</code>, with a push that keeps the normal history. Only the first time, set the Pages source to the root of <code>gh-pages</code>. If the existing Pages settings differ, it stops without replacing them on its own.</p><p>The published address is <strong><a href="https://manji6.github.io/jev-personalization/" target="_blank" rel="noreferrer">https://manji6.github.io/jev-personalization/</a></strong>, and the English version is at <strong><a href="https://manji6.github.io/jev-personalization/en/" target="_blank" rel="noreferrer">https://manji6.github.io/jev-personalization/en/</a></strong>. It takes a little time for GitHub to finish building and serving.</p><h3 id="if-only-the-first-activation-returns-403" tabindex="-1">If only the first activation returns 403 <a class="header-anchor" href="#if-only-the-first-activation-returns-403" aria-label="Permalink to “If only the first activation returns 403”">​</a></h3><p>If the GitHub connection lacks permission to edit Pages settings, the file push may succeed but only the first activation can fail. A repository administrator opens <a href="https://github.com/manji6/jev-personalization/settings/pages" target="_blank" rel="noreferrer">Settings → Pages</a>, chooses &quot;Deploy from a branch&quot; for Source, &quot;gh-pages&quot; for Branch and &quot;/ (root)&quot; for the folder, and saves. You don&#39;t need to paste an API key or an extra token into the text.</p><p>Once the source is set, you can update Help by pushing to <code>gh-pages</code> from then on. To update only the published files without using the Pages settings API, use <code>npm run help:publish -- --files-only</code>. Check the display at the published URL before treating the publication as complete.</p><h2 id="how-this-differs-from-releasing-the-app-to-production" tabindex="-1">How this differs from releasing the app to production <a class="header-anchor" href="#how-this-differs-from-releasing-the-app-to-production" aria-label="Permalink to “How this differs from releasing the app to production”">​</a></h2><p>Publishing Help updates only <code>gh-pages</code>. It doesn&#39;t deploy code to the app&#39;s Production or migrate the database.</p><p>If you change the app&#39;s reviewed commit, deploy it to Preview separately and move to Production after checking. Don&#39;t treat publishing Help as meaning the app has been released to production.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};